// ==========================================================================
// TABELA DE INFRAÇÕES DE TRÂNSITO — CheckMulta
//
// FONTE OFICIAL: Tabela de Código de Infrações RENAINF, publicada pela
// SENATRAN (Secretaria Nacional de Trânsito) em gov.br/transportes.
// Os dados de código, descrição, amparo legal, infrator, gravidade e órgão
// competente foram extraídos diretamente da planilha oficial, sem alteração.
//
// VALORES: não são armazenados por infração. São calculados a partir da
// gravidade, conforme o art. 258 do CTB, multiplicados pelo fator de
// agravamento quando houver (art. 258, § 2º). Quando o CONTRAN reajustar os
// valores, basta atualizar as quatro constantes em VALORES_BASE abaixo.
//
// PONTOS: conforme o art. 259 do CTB. Atribuídos somente quando o infrator
// é o condutor — proprietário, pessoa jurídica, pedestre e servidor público
// não recebem pontos na CNH.
// ==========================================================================

export type Gravidade = "leve" | "media" | "grave" | "gravissima" | "especial";

export interface Infracao {
  /** Código da infração, como aparece no auto (ex: "7471") */
  codigo: string;
  /** Desdobramento. 0 quando não há. */
  desdobramento: number;
  /** Identificador para a URL. "7471" ou "5029-1" quando há desdobramento. */
  slug: string;
  /** Descrição oficial, exatamente como consta na tabela da SENATRAN. */
  descricao: string;
  /** Artigo e inciso do CTB que fundamenta a autuação. */
  amparoLegal: string;
  /** Quem responde pela infração. */
  infrator: string;
  gravidade: Gravidade;
  /** Fator de agravamento. 1 quando não há; 0.5 nas infrações de pedestre. */
  multiplicador: number;
  /** Pontos na CNH. 0 quando o infrator não é o condutor. */
  pontos: number;
  orgaoCompetente: string;
}

/** Valores do art. 258 do CTB, com redação da Lei 13.281/2016. */
export const VALORES_BASE: Record<Gravidade, number> = {
  gravissima: 293.47,
  grave: 195.23,
  media: 130.16,
  leve: 88.38,
  especial: 0,
};

export const NOMES_GRAVIDADE: Record<Gravidade, string> = {
  gravissima: "Gravíssima",
  grave: "Grave",
  media: "Média",
  leve: "Leve",
  especial: "Penalidade específica",
};

/**
 * Valor da multa em reais.
 * Retorna null quando a infração não tem valor fixado pelo art. 258
 * (casos de penalidade específica prevista em outro dispositivo).
 */
export function calcularValor(infracao: Infracao): number | null {
  if (infracao.gravidade === "especial") return null;
  const base = VALORES_BASE[infracao.gravidade];
  return Math.round(base * infracao.multiplicador * 100) / 100;
}

/** Valor com o desconto de 40% do art. 284 do CTB (pagamento até o vencimento). */
export function calcularValorComDesconto(infracao: Infracao): number | null {
  const valor = calcularValor(infracao);
  if (valor === null) return null;
  return Math.round(valor * 0.6 * 100) / 100;
}

/** Formata em real brasileiro: 293.47 -> "R$ 293,47" */
export function formatarReal(valor: number): string {
  return valor.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL",
  });
}

/** Busca por código exato, com ou sem desdobramento. */
export function buscarPorSlug(slug: string): Infracao | undefined {
  return infracoes.find((i) => i.slug === slug);
}

/** Todas as entradas de um mesmo código (um código pode ter desdobramentos). */
export function buscarPorCodigo(codigo: string): Infracao[] {
  return infracoes.filter((i) => i.codigo === codigo);
}

/** Remove acentos e caixa, para busca textual tolerante. */
function normalizar(texto: string): string {
  return texto
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
}

/**
 * Busca por código ou por palavras da descrição.
 * Aceita "7471", "velocidade 50", "cnh vencida", "art 218".
 */
export function buscarInfracoes(termo: string, limite = 30): Infracao[] {
  const t = normalizar(termo).trim();
  if (!t) return [];

  // Só dígitos e hífen: trata como código
  if (/^[0-9-]+$/.test(t)) {
    const exatas = infracoes.filter(
      (i) => i.slug === t || i.codigo === t.replace(/-.*$/, "")
    );
    if (exatas.length) return exatas.slice(0, limite);
    return infracoes.filter((i) => i.codigo.startsWith(t)).slice(0, limite);
  }

  const palavras = t.split(/\s+/).filter(Boolean);
  return infracoes
    .filter((i) => {
      const alvo = normalizar(i.descricao + " " + i.amparoLegal);
      return palavras.every((p) => alvo.includes(p));
    })
    .slice(0, limite);
}

